"""Profiling: BLITZ_FPS=1 only reports when the runtime was built with BLITZ_PROFILE.

  profile.py BLITZCC PROGRAM.bb WORKDIR on|off
"""
import os
import subprocess
import sys


def main():
    blitzcc, source, work, mode = sys.argv[1], sys.argv[2], os.path.abspath(sys.argv[3]), sys.argv[4]
    os.makedirs(work, exist_ok=True)
    exe = os.path.join(work, "profile")
    subprocess.run([blitzcc, source, "-o", exe], check=True, stdout=subprocess.DEVNULL)
    result = subprocess.run([exe], env=dict(os.environ, BLITZ_FPS="1"), capture_output=True, text=True, timeout=60)
    reported = "fps:" in result.stderr
    if reported != (mode == "on"):
        print("profile: BLITZ_FPS=1 %s, but the runtime was built with profiling %s.\n%s" % ("reported" if reported else "was silent", mode, result.stderr))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
